"use strict";(self.webpackChunksketch_blog=self.webpackChunksketch_blog||[]).push([[2172],{6351(n,a,s){s.r(a),s.d(a,{_pageData:()=>i,default:()=>c});var e=s(641);const i=JSON.parse('{"path":"/notes/JavaScript/%E6%97%A5%E5%B8%B8%E7%AC%94%E8%AE%B0/Airbnb%20JavaScript%E9%A3%8E%E6%A0%BC%E6%8C%87%E5%8D%97%E6%91%98%E5%BD%95.html","title":"Airbnb JavaScript风格指南摘录","lang":"zh-CN","frontmatter":{"title":"Airbnb JavaScript风格指南摘录","date":"2023-05-30T00:00:00.000Z","tags":["JavaScript"]},"git":{},"filePathRelative":"notes/JavaScript/日常笔记/Airbnb JavaScript风格指南摘录.md"}'),l={name:"Airbnb JavaScript风格指南摘录.md"},c=(0,s(6262).A)(l,[["render",function(n,a,s,i,l,c){return(0,e.uX)(),(0,e.CE)("div",null,[...a[0]||(a[0]=[(0,e.Fv)('<h1 id="airbnb-javascript-风格指南摘录" tabindex="-1"><a class="header-anchor" href="#airbnb-javascript-风格指南摘录"><span>Airbnb JavaScript 风格指南摘录</span></a></h1><h3 id="对象浅拷贝" tabindex="-1"><a class="header-anchor" href="#对象浅拷贝"><span>对象浅拷贝</span></a></h3><p>对象浅拷贝时，更推荐使用扩展运算符（即<code>...</code>运算符），而不是<code>Object.assign</code>。获取对象指定的几个属性时，用对象的 rest 解构运算符（即 <code>...</code>运算符）更好。eslint:<code>prefer-object-spread</code>这一段不太好翻译出来， 大家看下面的例子就懂了。^.^</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">// very bad</span>\n<span class="line">const original = { a: 1, b: 2 };</span>\n<span class="line">const copy = Object.assign(original, { c: 3 }); // 改了 `original` ಠ_ಠ</span>\n<span class="line">delete copy.a; // so does this</span>\n<span class="line"></span>\n<span class="line">// bad</span>\n<span class="line">const original = { a: 1, b: 2 };</span>\n<span class="line">const copy = Object.assign({}, original, { c: 3 }); // copy =&gt; { a: 1, b: 2, c: 3 }</span>\n<span class="line"></span>\n<span class="line">// good es6 扩展运算符 ...</span>\n<span class="line">const original = { a: 1, b: 2 };</span>\n<span class="line">// 浅拷贝</span>\n<span class="line">const copy = { ...original, c: 3 }; // copy =&gt; { a: 1, b: 2, c: 3 }</span>\n<span class="line"></span>\n<span class="line">// rest 解构运算符</span>\n<span class="line">const { a, ...noA } = copy; // noA =&gt; { b: 2, c: 3 }</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><img src="http://os.zhaohs.cn/markdown/202305301129059.png" alt="image-20230530112901476"></p><blockquote><p>原文：<a href="https://github.com/lin-123/javascript" target="_blank" rel="noopener noreferrer">lin-123/javascript: eslint-config-airbnb 中文版 (github.com)</a></p></blockquote>',6)])])}]])}}]);